int main() {
    char s[10005];
    char oldStr[1005];
    char newStr[1005];
    char result[20005];

    if (fgets(s, sizeof(s), stdin) == NULL) return 0;
    if (fgets(oldStr, sizeof(oldStr), stdin) == NULL) return 0;

    if (fgets(newStr, sizeof(newStr), stdin) == NULL) {
        newStr[0] = '\0';
    }

    s[strcspn(s, "\r\n")] = '\0';
    oldStr[strcspn(oldStr, "\r\n")] = '\0';
    newStr[strcspn(newStr, "\r\n")] = '\0';

    int oldLen = strlen(oldStr);

    if (oldLen == 0) {
        printf("%s", s);
        return 0;
    }

    int i = 0;
    int j = 0;

    while (s[i] != '\0') {
        if (strncmp(&s[i], oldStr, oldLen) == 0) {
            i += oldLen;

            for (int k = 0; newStr[k] != '\0'; k++) {
                result[j++] = newStr[k];
            }
        } else {
            result[j++] = s[i++];
        }
    }

    result[j] = '\0';

    printf("%s", result);

    return 0;
}

